import json, subprocess, sys, os
sys.path.insert(0, '/app/tmp/work')
import gen, ref, random

def norm(resp):
    if 'error' in resp:
        return resp
    classes = {}
    for c in resp['classes']:
        sig = c['signature']
        assert sig not in classes, 'duplicate signature %s' % sig
        rep = c['representative']['or']
        key = tuple(sorted((l['atom'], l['negated']) for l in rep))
        classes[sig] = (c['members'], key)
    return {'version': resp['version'], 'classes': classes, 'queries': resp['queries']}

bad = 0
n = int(sys.argv[1]) if len(sys.argv) > 1 else 200
start = int(sys.argv[2]) if len(sys.argv) > 2 else 0
stats = {'classes':0, 'nonempty':0, 'queries':0, 'ambiguous':0, 'violating':0}
for seed in range(start, start + n):
    rng = random.Random(seed)
    req = gen.gen_request(rng)
    text = json.dumps(req)
    p = subprocess.run(['/app/submission/run.sh'], input=text.encode(), capture_output=True, cwd='/app/submission')
    if p.returncode != 0:
        print('SEED', seed, 'EXIT', p.returncode, p.stderr.decode()[:2000]); bad += 1; continue
    try:
        got = json.loads(p.stdout.decode())
    except Exception as e:
        print('SEED', seed, 'BADJSON', p.stdout[:400]); bad += 1; continue
    exp = ref.solve(json.loads(text))
    g = norm(got); e = norm(exp)
    stats['classes'] += len(e['classes']); stats['queries'] += len(e['queries'])
    if e['classes']: stats['nonempty'] += 1
    for q in e['queries']:
        if q['status']=='ambiguous': stats['ambiguous']+=1
        if q['status']=='violating': stats['violating']+=1
    if g != e:
        bad += 1
        print('SEED', seed, 'MISMATCH')
        print(' got:', json.dumps(g)[:1200])
        print(' exp:', json.dumps(e)[:1200])
        open('/app/tmp/work/fail_%d.json' % seed, 'w').write(text)
        if bad > 3: break
    else:
        # verify representative eligibility: check that rep clause is among ref members
        for sig, (cnt, key) in g['classes'].items():
            members = exp_classes = None
print('done, bad =', bad, 'stats', stats)
